import Link from "next/link";

export default function DashboardPage() {
    return (
        <div>
            {/* Welcome Section */}
            <div style={{ marginBottom: '2rem' }}>
                <h1 style={{ fontSize: '1.875rem', fontWeight: 700, marginBottom: '0.5rem' }}>Good afternoon, John! 👋</h1>
                <p style={{ color: 'var(--secondary-foreground)' }}>Here is what's happening with your Erasmus journey today.</p>
            </div>

            {/* Stats Grid */}
            <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
                gap: '1.5rem',
                marginBottom: '2rem'
            }}>
                {/* Visa Progress */}
                <div style={{ padding: '1.5rem', backgroundColor: 'var(--background)', borderRadius: '1rem', border: '1px solid var(--border)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1rem' }}>
                        <span style={{ fontWeight: 600 }}>Visa Checklist</span>
                        <span style={{ color: 'var(--primary)' }}>30%</span>
                    </div>
                    <div style={{ width: '100%', height: '8px', backgroundColor: 'var(--secondary)', borderRadius: '4px', overflow: 'hidden' }}>
                        <div style={{ width: '30%', height: '100%', backgroundColor: 'var(--primary)' }}></div>
                    </div>
                    <p style={{ fontSize: '0.875rem', color: 'var(--secondary-foreground)', marginTop: '0.75rem' }}>
                        3 documents pending for next week.
                    </p>
                </div>

                {/* Budget */}
                <div style={{ padding: '1.5rem', backgroundColor: 'var(--background)', borderRadius: '1rem', border: '1px solid var(--border)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1rem' }}>
                        <span style={{ fontWeight: 600 }}>Remaining Budget</span>
                        <span style={{ color: '#10b981' }}>Safe</span>
                    </div>
                    <p style={{ fontSize: '2rem', fontWeight: 700, margin: '0.5rem 0' }}>€ 2,450</p>
                    <p style={{ fontSize: '0.875rem', color: 'var(--secondary-foreground)' }}>
                        of € 3,000 total grant
                    </p>
                </div>

                {/* Next Trip */}
                <div style={{ padding: '1.5rem', backgroundColor: 'var(--background)', borderRadius: '1rem', border: '1px solid var(--border)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1rem' }}>
                        <span style={{ fontWeight: 600 }}>Next Trip</span>
                        <span>✈️</span>
                    </div>
                    <h3 style={{ fontSize: '1.25rem', fontWeight: 600 }}>Rome, Italy</h3>
                    <p style={{ fontSize: '0.875rem', color: 'var(--secondary-foreground)', marginTop: '0.25rem' }}>
                        in 14 days (Feb 15)
                    </p>
                </div>
            </div>

            {/* Main Sections */}
            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '2rem' }}>

                {/* Left Col: Next Actions */}
                <div>
                    <h3 style={{ fontSize: '1.25rem', fontWeight: 600, marginBottom: '1rem' }}>Next Actions</h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                        {/* Action Item */}
                        <div style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '1rem',
                            padding: '1rem',
                            backgroundColor: 'var(--background)',
                            borderRadius: '0.75rem',
                            border: '1px solid var(--border)'
                        }}>
                            <div style={{
                                width: '2rem',
                                height: '2rem',
                                borderRadius: '50%',
                                border: '2px solid var(--border)',
                                display: 'grid',
                                placeItems: 'center',
                                cursor: 'pointer'
                            }}></div>
                            <div>
                                <p style={{ fontWeight: 500 }}>Upload Passport Copy</p>
                                <p style={{ fontSize: '0.75rem', color: 'var(--secondary-foreground)' }}>Document • Due tomorrow</p>
                            </div>
                            <Link href="/dashboard/documents" style={{ marginLeft: 'auto', fontSize: '0.875rem', color: 'var(--primary)' }}>View</Link>
                        </div>

                        {/* Action Item */}
                        <div style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '1rem',
                            padding: '1rem',
                            backgroundColor: 'var(--background)',
                            borderRadius: '0.75rem',
                            border: '1px solid var(--border)'
                        }}>
                            <div style={{
                                width: '2rem',
                                height: '2rem',
                                borderRadius: '50%',
                                border: '2px solid var(--border)',
                                display: 'grid',
                                placeItems: 'center',
                                cursor: 'pointer'
                            }}></div>
                            <div>
                                <p style={{ fontWeight: 500 }}>Confirm Accommodation</p>
                                <p style={{ fontSize: '0.75rem', color: 'var(--secondary-foreground)' }}>Housing • Due in 3 days</p>
                            </div>
                            <Link href="/dashboard/checklist" style={{ marginLeft: 'auto', fontSize: '0.875rem', color: 'var(--primary)' }}>View</Link>
                        </div>
                    </div>
                </div>

                {/* Right Col: Quick Tips / Community */}
                <div>
                    <h3 style={{ fontSize: '1.25rem', fontWeight: 600, marginBottom: '1rem' }}>Community Trending</h3>
                    <div style={{
                        padding: '1rem',
                        backgroundColor: 'var(--background)',
                        borderRadius: '0.75rem',
                        border: '1px solid var(--border)'
                    }}>
                        <p style={{ fontWeight: 500, marginBottom: '0.5rem' }}>🏡 Best neighborhoods in Warsaw?</p>
                        <p style={{ fontSize: '0.875rem', color: 'var(--secondary-foreground)', marginBottom: '1rem' }}>
                            Looking for a student-friendly area near the university...
                        </p>
                        <Link href="/dashboard/forum" style={{ fontSize: '0.875rem', color: 'var(--primary)', fontWeight: 500 }}>Read discussion →</Link>
                    </div>
                </div>
            </div>
        </div>
    );
}
